    if (v.kpath === 'cert') { c.certStatus = 'pending'; DB.certRequests.unshift({ id: uid('cr'), coachId: c.id, diploma: v.dname || 'Diplôme d’éducateur sportif', issuer: v.issuer || '—', year: Number(v.year) || 2020, submitted: new Date().toISOString(), status: 'pending', reason: '', file: v.diploma }); }
